const test=require('node:test'),assert=require('node:assert/strict');
test('Town presets seed households matching their actual home footprints',async()=>{const {districtRecipe}=await import('../district-scenes.js');const {townSites}=await import('../town-life/tile-state.mjs');for(const [preset,count]of [['market',8],['civic',6]]){const r=districtRecipe('town',preset,41);assert.equal(r.townLife.households.length,count);assert.equal(r.requirements[0].items.filter(i=>i.asset==='GF-191').length,count);assert.equal(Object.keys(townSites(preset)).filter(k=>k.startsWith('home')).length,count);assert(!r.requirements[0].items.some(i=>['BA-0088','BA-0083'].includes(i.asset)));}});
test('placed copies advance independently and survive serialization, movement and undo',async()=>{const {districtRecipe}=await import('../district-scenes.js');const {townState,stepTownInstance}=await import('../town-life/tile-state.mjs');const {editComposition,compositionHistory}=await import('../board-state.js');const c={id:'town',revision:1,type:'town',cells:[{q:0,r:0}],recipe:districtRecipe('town','market',41),rendition:{scene:{object:{}}}};let board={version:1,id:'test',revision:0,cards:{'town@1':c},instances:[{instanceId:'a',cardId:'town',cardRevision:1,q:0,r:0,rotation:0},{instanceId:'b',cardId:'town',cardRevision:1,q:1,r:0,rotation:0}]};const history=compositionHistory(board);let next=stepTownInstance(board,'a');history.commit(next);assert.equal(townState(c,next.instances[0]).hour,6);assert.equal(townState(c,next.instances[1]).hour,5);assert.equal(c.recipe.townLife.hour,5);next=editComposition(next,'move',{instanceId:'a',q:0,r:1});assert.equal(next.instances[0].townLife.hour,6);assert.equal(JSON.parse(JSON.stringify(next)).instances[0].townLife.hour,6);assert.equal(townState(c,history.peek('undo').instances[0]).hour,5);});
test('both Town presets provide food, school and trade for thirty days',async()=>{const {townForPreset}=await import('../town-life/tile-state.mjs');const {advanceHour}=await import('../town-life/economy.mjs');for(const preset of ['market','civic']){let s=townForPreset(preset);for(let n=0;n<24*30;n++)s=advanceHour(s);assert(s.meals>0);assert(s.schoolHours>0);assert(s.transactions>0);assert(s.households.every(h=>h.wellbeing===100));}});
test('Town runtime attaches live actors at tile scale and terrain height for every rotation',async()=>{const T=await import('../vendor/three.module.js');const {attachTown,animateTown}=await import('../town-life/tile-view.mjs');const {townForPreset}=await import('../town-life/tile-state.mjs');for(let rotation=0;rotation<6;rotation++){const g=new T.Group(),s=townForPreset('market');s.hour=10;const root=attachTown(g,{rotation,center:{x:100,z:200}},'market',()=>s,()=>2,.1);assert.equal(root.children.length,s.households.reduce((n,h)=>n+h.adults+h.children,0));assert.equal(root.scale.x,.1);assert.equal(root.rotation.y,rotation*Math.PI/3);const first=root.children[0],before=first.position.clone();assert(animateTown(g,1));assert.notEqual(first.position.x,before.x);assert(Math.abs(first.position.y-2.04)<.1);}});
